/**
 * Content-line folding: a TypeScript port of meeting_ics.ical.fold (Python).
 * Folds at 75 octets, never splits a UTF-8 character. Pieces after the first start with one space.
 * Shared vectors (test/fixtures/fold-vectors.json) are generated by the Python function and checked here.
 */

const enc = new TextEncoder();

function octets(cp: number): number {
  if (cp < 0x80) return 1;
  if (cp < 0x800) return 2;
  if (cp < 0x10000) return 3;
  return 4;
}

export function fold(line: string): string[] {
  if (enc.encode(line).length <= 75) return [line];
  const out: string[] = [];
  let cur = '';
  let curlen = 0;
  const limit = 75;
  for (const ch of line) {
    // Lone surrogates encode as U+FFFD (3 octets), matching TextEncoder.
    const cp = ch.codePointAt(0)!;
    const n = cp >= 0xd800 && cp <= 0xdfff ? 3 : octets(cp);
    if (curlen + n > limit) {
      out.push(cur);
      cur = ' ';
      curlen = 1;
    }
    cur += ch;
    curlen += n;
  }
  out.push(cur);
  return out;
}

/** Fold and join with CRLF (no trailing CRLF). */
export function foldJoin(line: string): string {
  return fold(line).join('\r\n');
}
